\label{eq:hamilton_flow-b}
\frac{{\mathrm{d}}\boldsymbol{y}}{{\mathrm{d}}\tau} &=& - \frac{\partial\rho}{\partial\boldsymbol{y}} = \frac{\partial}{\partial\boldsymbol{x}}\, {\mathbb{I}}{\mathrm{m}} \left( - \frac{1}{\hbar} V (\boldsymbol{z}) \right),
\end{eqnarray}

